# Funções e diálogos da Pedreira. O padrão permanece: jogador fala -> NPC responde -> opções.
marker="function travelRoad(){"
helpers=r'''function travelQuarry(){const st=ensureCampaignMain();if(!['mq_09','mq_10','mq_11','mq_12','mq_13'].includes(st.mission)){toastMsg('As Pedreiras ainda não fazem parte da sua missão atual.');return}world='quarry';player.x=150;player.y=825;projectiles=[];spawnQuarryEncounter();save();updateHud();toastMsg('Pedreiras de Âmbar')}
function returnOrlaFromQuarry(){world='orla';player.x=1370;player.y=760;projectiles=[];goblins=[];save();updateHud();toastMsg('Retorno a Orla')}
function spawnQuarryEncounter(){const st=ensureCampaignMain(),pr=st.progress||{};goblins=[];if(st.mission==='mq_10'){const killed=pr.quarryKills||[];const pts=[{id:301,x:720,y:590},{id:302,x:1040,y:655},{id:303,x:1370,y:565}];goblins=pts.filter(e=>!killed.includes(e.id)).map(e=>({...e,r:20,hp:50,maxHp:50,dead:false,state:'idle',cooldown:.55+Math.random()*.55,windup:0,attackX:0,attackY:0,quarryEnemy:true,name:'Eco de Turno'}))}else if(st.mission==='mq_12'&&!pr.bossDefeated){const hp=Math.max(1,Number(pr.bossHp||340));goblins=[{x:1605,y:455,r:34,hp,maxHp:340,dead:false,id:380,state:'idle',cooldown:.6,windup:0,attackX:0,attackY:0,quarryBoss:true,boss:true,name:'Capataz de Horas'}]}}
function checkMQ10(){const st=ensureCampaignMain(),pr=st.progress||{};if(st.mission!=='mq_10')return;const brakes=(pr.brakes||[]).length,kills=(pr.quarryKills||[]).length;if(brakes>=3&&kills>=3){goblins=[];campaignReward('mq_10','mq_11',170,120,'Chave do Elevador');toastMsg('Nova missão: Última descida')}}
function talkAline(){const st=ensureCampaignMain(),pr=st.progress||{},cm=st.mission;if(cm==='mq_09'){if(!pr.metAline){setDialog(`<b>${player.name}</b><br><br>Olá. Vim de Orla para investigar o Livro de Pagamento e os turnos que não aparecem mais nos registros.<br><br><b>Aline Moura — Segurança da Pedreira</b><br><br>Sou Aline. Trabalho na segurança das Pedreiras desde a retomada desta região. Nos últimos dias, trabalhadores terminaram turnos inteiros e depois sumiram das folhas oficiais, como se nunca tivessem entrado aqui.`,[['Vou investigar',()=>{pr.metAline=true;st.progress=pr;writeCampaignMain(st);closeDialog();save();updateHud()}],['Quem é você?',()=>setDialog('<b>Aline Moura</b><br><br>Eu cuidava de segurança industrial antes da Catástrofe. Quando a pedreira voltou a operar, fiquei responsável por evacuação, acidentes e controle de turno. Não sou Desperta. Meu trabalho é garantir que quem entra aqui também saia daqui.',[['Voltar',()=>talkAline()],['Encerrar',closeDialog]])],['O que aconteceu?',()=>setDialog('<b>Aline Moura</b><br><br>Primeiro apareceram horas extras sem trabalhador. Depois apareceram trabalhadores sem hora. Agora há nomes que os colegas lembram, mas que não existem mais no livro. Comece pelo registro principal e compare com as folhas dos três setores.',[['Voltar',()=>talkAline()],['Encerrar',closeDialog]])],['Depois',closeDialog]]);return}const ready=pr.ledgerOpened&&(pr.shiftCards||[]).length>=3;if(ready){setDialog(`<b>${player.name}</b><br><br>Aline, encontrei três turnos que foram pagos, mas os nomes foram removidos do registro oficial.<br><br><b>Aline Moura</b><br><br>Então não é erro de contabilidade. Alguém está apagando pessoas e mantendo o trabalho delas dentro da produção. Vou lacrar uma cópia dessas páginas. As máquinas começaram a repetir o mesmo turno; precisamos parar isso agora.`,[['Registrar a prova',()=>{closeDialog();campaignReward('mq_09','mq_10',150,100,'Página do Livro de Pagamento');spawnQuarryEncounter();toastMsg('Nova missão: Freio de emergência')}],['Quem é você?',()=>setDialog('<b>Aline Moura</b><br><br>Segurança da pedreira. Hoje também sou testemunha do que aconteceu com esses turnos.',[['Voltar',()=>talkAline()],['Encerrar',closeDialog]])],['Depois',closeDialog]]);return}setDialog(`<b>${player.name}</b><br><br>Ainda estou conferindo os registros.<br><br><b>Aline Moura</b><br><br>Abra o livro principal e compare as folhas dos três setores. Só volte quando tiver certeza dos nomes que foram retirados.`,[['Quem é você?',()=>setDialog('<b>Aline Moura</b><br><br>Cuido da segurança das Pedreiras e dos registros de entrada e saída.',[['Voltar',()=>talkAline()],['Encerrar',closeDialog]])],['Depois',closeDialog]]);return}if(cm==='mq_10'){setDialog(`<b>${player.name}</b><br><br>As máquinas estão repetindo o turno.<br><br><b>Aline Moura</b><br><br>Use os freios de emergência dos três setores. Os Ecos de Turno estão surgindo perto das correias; elimine-os antes que alguém tente religar o sistema.`,[['Entendido',closeDialog],['Depois',closeDialog]]);return}if(cm==='mq_11'){setDialog(`<b>${player.name}</b><br><br>As prensas pararam. Qual é o próximo passo?<br><br><b>Aline Moura</b><br><br>Há um elevador de manutenção que não aparece na planta atual. Três trabalhadores foram vistos descendo por ele antes de desaparecerem do controle de turno. Encontre-os e abra a rota de emergência.`,[['Vou descer',closeDialog],['Depois',closeDialog]]);return}if(cm==='mq_12'){setDialog(`<b>${player.name}</b><br><br>Os trabalhadores estão seguros. Ainda falta o Capataz.<br><br><b>Aline Moura</b><br><br>Ele está preso ao relógio central da pedreira. Enquanto aquele registro continuar funcionando, os turnos podem recomeçar. Quebre o ciclo e traga o relógio de volta.`,[['Vou terminar isso',closeDialog],['Depois',closeDialog]]);return}setDialog('<b>Aline Moura</b><br><br>Os turnos voltaram a ser contados por pessoas, não por horas vazias. É um começo.')}
function inspectPayrollLedger(){const st=ensureCampaignMain(),pr=st.progress||{};if(st.mission!=='mq_09')return;if(!pr.metAline){toastMsg('Fale com Aline antes de mexer nos registros.');return}if(pr.ledgerOpened){toastMsg('Livro de Pagamento já conferido.');return}setDialog(`<b>Livro de Pagamento</b><br><br>Há valores pagos para equipes inteiras, mas várias linhas de nome foram raspadas e reescritas. As somas continuam fechando mesmo quando as pessoas desaparecem do registro.`,[['Marcar páginas suspeitas',()=>{pr.ledgerOpened=true;pr.shiftCards=pr.shiftCards||[];st.progress=pr;writeCampaignMain(st);closeDialog();save();updateHud();toastMsg('Livro marcado. Compare os três setores.')}],['Depois',closeDialog]])}
function inspectShiftCard(id,name){const st=ensureCampaignMain(),pr=st.progress||{};if(st.mission!=='mq_09'||!pr.ledgerOpened)return;pr.shiftCards=pr.shiftCards||[];if(pr.shiftCards.includes(id)){toastMsg('Turno já comparado.');return}setDialog(`<b>${name}</b><br><br>A folha registra horas, equipamento usado e pagamento, mas o campo do trabalhador foi apagado. Uma anotação de manutenção conserva parte do nome original.`,[['Registrar inconsistência',()=>{pr.shiftCards.push(id);st.progress=pr;writeCampaignMain(st);closeDialog();save();updateHud();toastMsg(`Turno comparado ${pr.shiftCards.length}/3`)}],['Depois',closeDialog]])}
function activateQuarryBrake(id){const st=ensureCampaignMain(),pr=st.progress||{};if(st.mission!=='mq_10')return;pr.brakes=pr.brakes||[];if(pr.brakes.includes(id)){toastMsg('Freio já acionado.');return}pr.brakes.push(id);st.progress=pr;writeCampaignMain(st);save();toastMsg(`Freio de emergência ${pr.brakes.length}/3 acionado`);checkMQ10()}
function descendQuarry(){const st=ensureCampaignMain(),pr=st.progress||{};if(st.mission!=='mq_11')return;if(pr.deep){toastMsg('O elevador já está no nível inferior.');return}if(!ensureInventory()['Chave do Elevador']){toastMsg('Você não possui a chave do elevador.');return}pr.deep=true;st.progress=pr;writeCampaignMain(st);player.x=1170;player.y=810;save();updateHud();toastMsg('Nível inferior da Pedreira')}
function rescueQuarryWorker(id,name){const st=ensureCampaignMain(),pr=st.progress||{};if(st.mission!=='mq_11'||!pr.deep)return;pr.rescuedWorkers=pr.rescuedWorkers||[];if(pr.rescuedWorkers.includes(id)){toastMsg('Trabalhador já resgatado.');return}setDialog(`<b>${name}</b><br><br>O trabalhador está exausto e repete que o turno ainda não terminou, mesmo com todas as máquinas paradas.`,[['Levar para a rota segura',()=>{pr.rescuedWorkers.push(id);st.progress=pr;writeCampaignMain(st);closeDialog();save();updateHud();toastMsg(`Trabalhadores localizados ${pr.rescuedWorkers.length}/3`)}],['Depois',closeDialog]])}
function openQuarryEmergencyRoute(){const st=ensureCampaignMain(),pr=st.progress||{};if(st.mission!=='mq_11')return;if((pr.rescuedWorkers||[]).length<3){toastMsg('Ainda há trabalhadores presos.');return}setDialog(`<b>Rota de emergência</b><br><br>A passagem de manutenção leva os três trabalhadores para a área segura. No mesmo instante, o relógio central da pedreira começa a bater fora de ritmo.`,[['Abrir passagem',()=>{closeDialog();campaignReward('mq_11','mq_12',200,140,'Crachá de Turno Recuperado');spawnQuarryEncounter();toastMsg('Nova missão: O relógio do capataz')}],['Depois',closeDialog]])}
'''
rep(marker,helpers+'\n'+marker,'quarry helpers')

