sub(r"function hitGoblin\(g,d\)\{.*?\}\nfunction basicAttack",r'''function hitGoblin(g,d){if(g.dead)return;g.hp-=d;if(g.hp<=0){g.hp=0;g.dead=true;g.state='dead';if(world==='camp'){gainXP(8);player.gold=Number(player.gold||0)+5;addItem('Fragmento de Goblin',1);toastMsg('Drop: +8 EXP • +5 Ouro • Fragmento de Goblin');save()}else if(world==='cistern'&&g.boss){const st=ensureCampaignMain(),pr=st.progress||{};pr.bossDefeated=true;pr.bossHp=0;st.progress=pr;writeCampaignMain(st);campaignReward('mq_04','mq_05',180,120,'Inscrição de Namar');toastMsg('BOSS derrotado • Drop: Inscrição de Namar • Capítulo 1 concluído')}else if(world==='road'&&g.roadBoss){const st=ensureCampaignMain(),pr=st.progress||{};pr.bossDefeated=true;pr.bossHp=0;st.progress=pr;writeCampaignMain(st);campaignReward('mq_08','mq_09',240,180,'Selo do Cobrador');goblins=[];toastMsg('O Cobrador derrotado • Capítulo 2 concluído')}else if(world==='road'&&g.roadEnemy){const st=ensureCampaignMain(),pr=st.progress||{};pr.roadKills=pr.roadKills||[];if(!pr.roadKills.includes(g.id))pr.roadKills.push(g.id);st.progress=pr;writeCampaignMain(st);gainXP(12);player.gold=Number(player.gold||0)+7;addItem('Fragmento de Lacre',1);save();toastMsg('Drop: +12 EXP • +7 Ouro • Fragmento de Lacre');checkMQ06()}else if(world==='quarry'&&g.quarryBoss){const st=ensureCampaignMain(),pr=st.progress||{};pr.bossDefeated=true;pr.bossHp=0;st.progress=pr;writeCampaignMain(st);campaignReward('mq_12','mq_13',320,250,'Relógio-Registro do Capataz');goblins=[];toastMsg('Capataz de Horas derrotado • Capítulo 3 concluído')}else if(world==='quarry'&&g.quarryEnemy){const st=ensureCampaignMain(),pr=st.progress||{};pr.quarryKills=pr.quarryKills||[];if(!pr.quarryKills.includes(g.id))pr.quarryKills.push(g.id);st.progress=pr;writeCampaignMain(st);gainXP(15);player.gold=Number(player.gold||0)+12;addItem('Lasca de Âmbar',1);save();toastMsg('Drop: +15 EXP • +12 Ouro • Lasca de Âmbar');checkMQ10()}}else if(world==='cistern'&&g.boss){const st=ensureCampaignMain(),pr=st.progress||{};pr.bossHp=g.hp;st.progress=pr;writeCampaignMain(st)}else if(world==='road'&&g.roadBoss){const st=ensureCampaignMain(),pr=st.progress||{};pr.bossHp=g.hp;st.progress=pr;writeCampaignMain(st)}else if(world==='quarry'&&g.quarryBoss){const st=ensureCampaignMain(),pr=st.progress||{};pr.bossHp=g.hp;st.progress=pr;writeCampaignMain(st)}updateHud()}
function basicAttack''','quarry combat')

sub(r"function hurtPlayer\(d\)\{.*?\}\nfunction updateGoblin",r'''function hurtPlayer(d){player.hp=Math.max(0,player.hp-d);dangerFlash.style.opacity=.28;setTimeout(()=>dangerFlash.style.opacity=0,110);if(player.hp<=0){player.hp=player.maxHp;const sp=world==='cistern'?{x:130,y:630}:world==='road'?{x:150,y:720}:world==='quarry'?{x:150,y:825}:{x:160,y:610};player.x=sp.x;player.y=sp.y;for(const g of goblins){if(!g.dead){g.state='idle';g.cooldown=.8;g.windup=0}}toastMsg('Você caiu e retornou ao ponto seguro.');save()}updateHud()}
function updateGoblin''','quarry respawn')

# Interações: Orla -> Pedreiras e objetivos do mapa.
camp_return=" if(world==='camp'&&goblins.filter(g=>g.dead).length>=5&&near(camp.returnPortal,86)){setDialog('<b>Portal de retorno</b><br>A missão foi concluída. Volte à Guilda para entregar a prova.',[['Retornar à cidade',()=>{closeDialog();returnCity()}],['Ficar',closeDialog]])}"
quarry_interactions=r''' if(world==='orla'){
  const cm=currentCampaignMission();if(['mq_09','mq_10','mq_11','mq_12','mq_13'].includes(cm)&&near(quarryDeparture,88)){travelQuarry();return}
 }
 if(world==='quarry'){
  const cm=currentCampaignMission(),pr=progressMain();
  if(near(quarry.returnGate,82)){returnOrlaFromQuarry();return}
  if(near(quarry.aline,76)){talkAline();return}
  if(cm==='mq_09'&&near(quarry.ledger,74)){inspectPayrollLedger();return}
  if(cm==='mq_09'&&pr.ledgerOpened){for(const q of quarry.shiftCards)if(!(pr.shiftCards||[]).includes(q.id)&&near(q,70)){inspectShiftCard(q.id,q.name);return}}
  if(cm==='mq_10'){for(const b of quarry.brakes)if(!(pr.brakes||[]).includes(b.id)&&near(b,72)){activateQuarryBrake(b.id);return}}
  if(cm==='mq_11'&&near(quarry.elevator,82)){descendQuarry();return}
  if(cm==='mq_11'&&pr.deep){for(const w of quarry.workers)if(!(pr.rescuedWorkers||[]).includes(w.id)&&near(w,72)){rescueQuarryWorker(w.id,w.name);return}}
  if(cm==='mq_11'&&pr.deep&&near(quarry.emergencyGate,82)){openQuarryEmergencyRoute();return}
 }
'''
rep(camp_return,quarry_interactions+camp_return,'quarry interactions')

# Navegação visual do Capítulo 3.
sub(r"function target\(\)\{.*?\}\nfunction arrowToTarget",r'''function target(){if(world==='camp'&&mission===S.GOBLINS){const alive=goblins.find(g=>!g.dead);return alive||camp.returnPortal}if(world==='city'){if(mission===S.GO_GUILD||mission===S.RETURN_GUILD)return city.guildDoor;if(mission===S.PORTAL)return city.portal;if(mission===S.DONE&&currentCampaignMission())return orlaDeparture}if(world==='guild'){if(mission===S.REGISTER||mission===S.REPORT)return guild.reception;if(mission===S.CAPTAIN||mission===S.CAPTAIN_AFTER)return guild.captain;if(mission===S.BOARD)return guild.board;if(mission===S.PORTAL)return guild.exit}if(world==='orla'){const cm=currentCampaignMission(),pr=progressMain();if(cm==='mq_01')return orla.saira;if(cm==='mq_02')return orla.residents.find(r=>!(pr.rescued||[]).includes(r.id))||orla.saira;if(cm==='mq_03')return orla.clues.find(q=>!(pr.clues||[]).includes(q.id))||orla.ines;if(cm==='mq_04')return orla.cisternDoor;if(['mq_05','mq_06','mq_07','mq_08'].includes(cm))return roadDeparture;if(['mq_09','mq_10','mq_11','mq_12','mq_13'].includes(cm))return quarryDeparture}if(world==='cistern'){const cm=currentCampaignMission(),pr=progressMain();if(cm==='mq_04'){const v=cistern.valves.find(v=>!(pr.valves||[]).includes(v.id));if(v)return v;return goblins.find(g=>!g.dead)||cistern.exit}if(cm==='mq_05')return cistern.returnPortal}if(world==='road'){const cm=currentCampaignMission(),pr=progressMain();if(cm==='mq_05')return pr.metLio?road.firstGate:road.lio;if(cm==='mq_06'){const l=road.lanterns.find(x=>!(pr.lanterns||[]).includes(x.id));if(l)return l;return goblins.find(g=>!g.dead)||road.lio}if(cm==='mq_07')return road.manifests.find(m=>!(pr.manifests||[]).includes(m.id))||road.lio;if(cm==='mq_08')return goblins.find(g=>!g.dead)||road.finalGate;if(cm==='mq_09')return road.returnGate}if(world==='quarry'){const cm=currentCampaignMission(),pr=progressMain();if(cm==='mq_09'){if(!pr.metAline)return quarry.aline;if(!pr.ledgerOpened)return quarry.ledger;return quarry.shiftCards.find(q=>!(pr.shiftCards||[]).includes(q.id))||quarry.aline}if(cm==='mq_10'){const b=quarry.brakes.find(x=>!(pr.brakes||[]).includes(x.id));if(b)return b;return goblins.find(g=>!g.dead)||quarry.aline}if(cm==='mq_11'){if(!pr.deep)return quarry.elevator;const w=quarry.workers.find(x=>!(pr.rescuedWorkers||[]).includes(x.id));return w||quarry.emergencyGate}if(cm==='mq_12')return goblins.find(g=>!g.dead)||quarry.bossPoint;if(cm==='mq_13')return quarry.returnGate}return null}
function arrowToTarget''','chapter3 targets')

# Arte 2D simples da pedreira, sem alterar a base de personagens/movimento.
insert_draw=r'''function drawQuarryDepartureMarker(){const cm=currentCampaignMission();if(!['mq_09','mq_10','mq_11','mq_12','mq_13'].includes(cm))return;ctx.fillStyle='#6f5233';ctx.fillRect(quarryDeparture.x-48,quarryDeparture.y-25,96,50);ctx.fillStyle='#d2a24c';ctx.fillRect(quarryDeparture.x+33,quarryDeparture.y-67,9,45);label('PEDREIRAS DE ÂMBAR',quarryDeparture.x-82,quarryDeparture.y-76,'#f0cb86',13)}
function drawQuarry(){ctx.fillStyle='#312820';ctx.fillRect(0,0,quarry.w,quarry.h);ctx.fillStyle='#5a4732';for(let x=120;x<1820;x+=210){ctx.fillRect(x,120,120,90);ctx.fillStyle='#8a642f';ctx.fillRect(x+18,148,24,24);ctx.fillStyle='#5a4732'}ctx.fillStyle='#49351f';ctx.fillRect(420,530,1030,190);ctx.fillStyle='#191919';for(let x=480;x<1430;x+=150)ctx.fillRect(x,690,110,20);label('PEDREIRAS DE ÂMBAR',690,78,'#efcc86',21);label('Retorno a Orla',55,802,'#ddd');const cm=currentCampaignMission(),pr=progressMain();npc(quarry.aline.x,quarry.aline.y,'Aline Moura','#c89b7b',cm==='mq_09'&&(!pr.metAline||(pr.ledgerOpened&&(pr.shiftCards||[]).length>=3));ctx.fillStyle='#d4bd8b';ctx.fillRect(quarry.ledger.x-22,quarry.ledger.y-16,44,32);if(cm==='mq_09')label('Livro de Pagamento',quarry.ledger.x-55,quarry.ledger.y-28,'#f1d7a0');if(cm==='mq_09'&&pr.ledgerOpened)for(const q of quarry.shiftCards){const done=(pr.shiftCards||[]).includes(q.id);ctx.fillStyle=done?'#65775d':'#d0bc91';ctx.fillRect(q.x-14,q.y-10,28,20);if(!done)label(q.name,q.x-55,q.y-22,'#ead7ad')}for(const b of quarry.brakes){const done=(pr.brakes||[]).includes(b.id);ctx.fillStyle=done?'#5d765f':'#a85c42';ctx.fillRect(b.x-16,b.y-28,32,56);if(cm==='mq_10')label(done?'Freio acionado':'Freio de emergência',b.x-52,b.y-40,done?'#9bd0a1':'#efb18d')}ctx.fillStyle='#514133';ctx.fillRect(quarry.elevator.x-50,quarry.elevator.y-55,100,110);label('ELEVADOR',quarry.elevator.x-42,quarry.elevator.y-68,'#d7c19a');if(cm==='mq_11'&&pr.deep)for(const w of quarry.workers)if(!(pr.rescuedWorkers||[]).includes(w.id))npc(w.x,w.y,w.name,'#aaa398',true);ctx.fillStyle='#40352d';ctx.fillRect(quarry.emergencyGate.x-45,quarry.emergencyGate.y-60,90,120);if(cm==='mq_11'&&pr.deep)label('ROTA DE EMERGÊNCIA',quarry.emergencyGate.x-78,quarry.emergencyGate.y-73,'#ddd');for(const g of goblins){if(g.dead)continue;if(g.state==='windup'){ctx.fillStyle='#d33a';ctx.beginPath();ctx.arc(g.attackX,g.attackY,g.quarryBoss?66:50,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#ff6565';ctx.stroke()}ctx.fillStyle=g.quarryBoss?'#b47c35':'#80623c';ctx.beginPath();ctx.arc(g.x,g.y,g.r,0,Math.PI*2);ctx.fill();label(g.name||'Eco de Turno',g.x-(g.quarryBoss?58:38),g.y-g.r-12,g.quarryBoss?'#ffd08a':'#e3c99f',g.quarryBoss?15:12);ctx.fillStyle='#222';ctx.fillRect(g.x-40,g.y+g.r+9,80,6);ctx.fillStyle='#b84b4b';ctx.fillRect(g.x-40,g.y+g.r+9,80*g.hp/g.maxHp,6)}}
'''
s=s.replace('function drawCamp(){',insert_draw+'function drawCamp(){',1)

sub(r"function draw\(\)\{.*?\}\nfunction label",r'''function draw(){ctx.clearRect(0,0,W,H);if(!player)return;const map=mapForWorld();cam.x=Math.max(0,Math.min(map.w-W,player.x-W/2));cam.y=Math.max(0,Math.min(map.h-H,player.y-H/2));ctx.save();ctx.translate(-cam.x,-cam.y);if(world==='city')drawCity();else if(world==='guild')drawGuild();else if(world==='orla'){drawOrla();drawRoadDepartureMarker();drawQuarryDepartureMarker()}else if(world==='cistern')drawCistern();else if(world==='road')drawRoad();else if(world==='quarry')drawQuarry();else drawCamp();drawPlayer();ctx.restore();arrowToTarget();drawAim();updateHint()}
function label''','quarry draw loop')

sub(r"function currentInteract\(\)\{.*?\}\nfunction updateHint",r'''function currentInteract(){if(!player)return'';if(world==='city'){if(near(city.guildDoor,82))return'Entrar na Guilda';if(near({x:470,y:500},78))return'Davi Moura';if(near({x:1080,y:480},78))return'Breno Carvalho';if(near(city.portal,82)&&mission===S.PORTAL)return'Portal Rank F';const cs=readCampaignMain();if(cs&&cs.unlocked&&near(orlaDeparture,82))return'Viajar para Orla'}if(world==='guild'){if(near(guild.exit,82))return'Sair da Guilda';if(near(guild.reception,78))return'Elena Duarte';if(near(guild.captain,78))return'Raul Vilar';if(near({x:520,y:290},76))return'Caio Nunes';if(near({x:570,y:360},76))return'Mirela Santos';if(near(guild.board,78))return'Quadro de Missões'}if(world==='orla'){const cm=currentCampaignMission(),pr=progressMain();if(near(orla.returnGate,82))return'Voltar à Cidade Inicial';if(near(orla.saira,78))return'Saira Vento';if(near(orla.ines,78))return'Inês Lume';if(['mq_05','mq_06','mq_07','mq_08'].includes(cm)&&near(roadDeparture,88))return'Seguir pela Estrada das Lanternas';if(['mq_09','mq_10','mq_11','mq_12','mq_13'].includes(cm)&&near(quarryDeparture,88))return'Viajar para as Pedreiras de Âmbar';if(cm==='mq_02'&&orla.residents.some(r=>!(pr.rescued||[]).includes(r.id)&&near(r,75)))return'Resgatar morador';if(cm==='mq_03'&&orla.clues.some(q=>!(pr.clues||[]).includes(q.id)&&near(q,75)))return'Investigar evidência';if(cm==='mq_04'&&near(orla.cisternDoor,90))return'Entrar na Cisterna'}if(world==='cistern'){const cm=currentCampaignMission(),pr=progressMain();if(cm==='mq_04'&&near(cistern.exit,82))return'Sair da Cisterna';if(cm==='mq_04'&&cistern.valves.some(v=>!(pr.valves||[]).includes(v.id)&&near(v,75)))return'Interromper válvula';if(cm==='mq_05'&&near(cistern.returnPortal,88))return'Retornar a Orla'}if(world==='road'){const cm=currentCampaignMission(),pr=progressMain();if(near(road.returnGate,82))return'Voltar para Orla';if(near(road.lio,78))return'Lio';if(cm==='mq_05'&&near(road.firstGate,78))return'Inspecionar a cancela';if(cm==='mq_06'&&road.lanterns.some(l=>!(pr.lanterns||[]).includes(l.id)&&near(l,75)))return'Reativar lanterna';if(cm==='mq_07'&&road.manifests.some(m=>!(pr.manifests||[]).includes(m.id)&&near(m,75)))return'Recolher manifesto'}if(world==='quarry'){const cm=currentCampaignMission(),pr=progressMain();if(near(quarry.returnGate,82))return'Voltar para Orla';if(near(quarry.aline,78))return'Aline Moura';if(cm==='mq_09'&&near(quarry.ledger,75))return'Conferir Livro de Pagamento';if(cm==='mq_09'&&pr.ledgerOpened&&quarry.shiftCards.some(q=>!(pr.shiftCards||[]).includes(q.id)&&near(q,75)))return'Comparar folha de turno';if(cm==='mq_10'&&quarry.brakes.some(b=>!(pr.brakes||[]).includes(b.id)&&near(b,75)))return'Acionar freio de emergência';if(cm==='mq_11'&&!pr.deep&&near(quarry.elevator,82))return'Descer pelo elevador';if(cm==='mq_11'&&pr.deep&&quarry.workers.some(w=>!(pr.rescuedWorkers||[]).includes(w.id)&&near(w,75)))return'Resgatar trabalhador';if(cm==='mq_11'&&pr.deep&&near(quarry.emergencyGate,82))return'Abrir rota de emergência'}if(world==='camp'&&goblins.filter(g=>g.dead).length>=5&&near(camp.returnPortal,82))return'Portal de retorno';return''}
function updateHint''','quarry hints')

# Clique direto em Aline, igual aos demais NPCs.
needle="if(world==='road'&&near(road.lio,90)&&clicked(road.lio,36)){talkLio();return}basicAttack(wx-player.x,wy-player.y)"
replace="if(world==='road'&&near(road.lio,90)&&clicked(road.lio,36)){talkLio();return}if(world==='quarry'&&near(quarry.aline,90)&&clicked(quarry.aline,36)){talkAline();return}basicAttack(wx-player.x,wy-player.y)"
rep(needle,replace,'Aline mouse interaction')

for needle in ['Pedreiras de Âmbar','Aline Moura','Capataz de Horas','Eco de Turno','Livro de Pagamento','Relógio-Registro do Capataz','mq_12','mq_13']:
    if needle not in s:
        raise SystemExit(f'validation failed: {needle}')

p.write_text(s,encoding='utf-8')